mapper.update:
update shebao_payment_plan_detail
set distribution_result = 'failed',
    fail_reason = #{reason}
where plan_id = #{planId}
  and del_flag = '0'
  and id_card_no = #{idCardNo}

mapper.select:
select null as id, null as plan_id, bd.id as determination_id, bdi.id as determination_item_id, bd.subsidy_person_id as subsidy_person_id, bdi.subsidy_type, sso.street_name, svc.village_name, sp.name as person_name, coalesce(bd.id_card_no, sp.id_card_no) as id_card_no, date_format(#{businessPeriod}, '%Y-%m') as business_period, date_format(#{businessPeriod}, '%Y-%m') as payment_month, ifnull(bdi.subsidy_standard, 0) as monthly_amount, 0 as supplement_amount, null as supplement_start_month, null as supplement_end_month, null as supplement_source, null as supplement_source_id, ifnull(bdi.subsidy_standard, 0) as distribution_amount, null as distribution_date, bd.grant_org, bd.account_name, bd.bank_account, bd.relation_to_insured from benefit_determination_item bdi left join benefit_determination bd on bdi.determination_id = bd.id left join shebao_subsidy_person sp on bd.subsidy_person_id = sp.id left join shebao_street_office sso on sp.street_office_id = sso.id left join shebao_village_committee svc on sp.village_committee_id = svc.id where bd.del_flag = '0' and bdi.del_flag = '0' and bd.approval_status = 'approved' and ifnull(bdi.benefit_status, '0') = '0' and bdi.subsidy_type = #{subsidyType} and not exists ( select 1 from shebao_payment_plan_detail pd left join shebao_payment_plan pp on pd.plan_id = pp.id and pp.del_flag = '0' where pd.determination_item_id = bdi.id and pd.business_period = #{businessPeriod} and pd.del_flag = '0'
and pd.plan_id <> #{excludePlanId}
) order by bdi.id asc

select d.id as id, d.plan_id as planId, p.batch_no as batchNo, date_format(d.business_period, '%Y-%m') as businessPeriod, d.subsidy_type as subsidyType, d.person_name as personName, d.id_card_no as idCardNo, d.distribution_amount as distributionAmount, d.bank_account as bankAccount, d.account_name as accountName, d.grant_org as grantOrg, d.fail_reason as failReason, d.village_name as villageName, d.street_name as streetName, d.payment_month as paymentMonth from shebao_payment_plan_detail d inner join shebao_payment_plan p on p.id = d.plan_id and p.del_flag = '0' where d.del_flag = '0' and d.distribution_result = 'failed' and p.finance_status = 'finance_approved'
and p.batch_no = #{req.batchNo}
and d.person_name like concat('%', #{req.personName}, '%')
and d.subsidy_type = #{req.subsidyType}
and d.business_period = #{req.businessPeriodDate}
and d.fail_reason like concat('%', #{req.failReason}, '%')
order by p.batch_no desc, d.id asc

select d.id, d.plan_id as planId, p.batch_no as batchNo, p.determination_type as determinationType, d.subsidy_person_id as subsidyPersonId, d.subsidy_type as subsidyType, d.street_name as streetName, d.village_name as villageName, d.person_name as personName, d.id_card_no as idCardNo, date_format(d.business_period, '%Y-%m') as businessPeriod, d.monthly_amount as monthlyAmount, d.supplement_amount as supplementAmount, date_format(d.supplement_start_month, '%Y-%m') as supplementStartMonth, date_format(d.supplement_end_month, '%Y-%m') as supplementEndMonth, d.distribution_amount as distributionAmount, date_format(d.distribution_date, '%Y-%m-%d') as distributionDate, d.grant_org as grantOrg, d.account_name as accountName, d.bank_account as bankAccount, d.relation_to_insured as relationToInsured, d.fail_reason as failReason, p.distribution_status as planDistributionStatus, d.distribution_result as distributionResult, case when ifnull(p.distribution_status, '') <> 'completed' then 'distributing' when d.distribution_result = 'failed' then 'failed' else 'paid' end as payStatus from shebao_payment_plan_detail d inner join shebao_payment_plan p on p.id = d.plan_id and p.del_flag = '0' where d.del_flag = '0' and p.finance_status = 'finance_approved'
and date_format(d.business_period, '%Y-%m') = #{req.businessPeriod}
and p.determination_type = #{req.determinationType}
and d.subsidy_type = #{req.subsidyType}
and d.grant_org = #{req.grantOrg}
and d.id_card_no like concat('%', #{req.idCardNo}, '%')
and d.person_name like concat('%', #{req.personName}, '%')
and p.batch_no like concat('%', #{req.batchNo}, '%')
and ( case when ifnull(p.distribution_status, '') <> 'completed' then 'distributing' when d.distribution_result = 'failed' then 'failed' else 'paid' end ) = #{req.payStatus}
order by d.id desc
